/*selectBuyerMpSoUniformReqCompanyList*/
SELECT	A.COMPANY_CODE AS CODE,
		(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.COMPANY_CODE) AS TEXT1
FROM	ICOMCOD2 A
WHERE	1=1
AND		A.TYPE = 'ST01'
AND		A.TEXT2 = #{SEARCH1}
AND		A.CODE = #{SEARCH2}
AND		A.FLAG = 'Y'

