/*updateBuyerMpSoUniformReq*/

		UPDATE	ICOMCART
		SET		CART_QTY = #{CART_QTY},
				REMARK = #{REMARK}
		WHERE	1=1
		AND		BUYER = #{st_buyer}
		AND		USER_ID = #{st_user_id}
		AND		USE_FLAG = 'S'
		AND		BUYER_ITEM_NO = #{BUYER_ITEM_NO}
		AND		CONTRACT_NO = #{CONTRACT_NO}
		AND		CONTRACT_SEQ = #{CONTRACT_SEQ}
		AND		SEQ = #{SEQ}

/*deleteBuyerMpSoUniformReq*/

		DELETE	ICOMCART
		WHERE	1=1
		AND		BUYER = #{st_buyer}
		AND		USER_ID = #{st_user_id}
		AND		USE_FLAG = 'S'
		AND		BUYER_ITEM_NO = #{BUYER_ITEM_NO}
		AND		CONTRACT_NO = #{CONTRACT_NO}
		AND		CONTRACT_SEQ = #{CONTRACT_SEQ}
		AND		SEQ = #{SEQ}
